import os
from openpyxl import load_workbook
inp = os.environ['IN_XLSX']
out = os.environ['OUT_XLSX']
wb = load_workbook(inp, data_only=True)
src = wb['BZTB']
rows = []
for r in src.iter_rows(min_row=1, max_row=src.max_row, values_only=True):
    a,b,c,d = r[0],r[1],r[2],r[3]
    if b is None:
        continue
    bs = str(b)
    if not (bs.startswith('COS Pass') or bs.startswith('COS Comm') or bs.startswith('COS W/S')):
        continue
    if 'Used' not in bs:
        continue
    if str(a) == '398726':
        continue
    rows.append((a,b,c,d))
print('count', len(rows))
for x in rows:
    print(x)
dest = wb['Tema UV COS']
# clear target area
for rr in range(1, 23):
    for cc in range(1,5):
        dest.cell(row=rr, column=cc).value = None
for i, row in enumerate(rows):
    rr = i+1
    for j, val in enumerate(row):
        dest.cell(row=rr, column=j+1).value = val
wb.save(out)
print('saved')
